solutionSql:
CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL,
  name TEXT NOT NULL
);

CREATE TABLE posts (
  id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL,
  user_id INTEGER NOT NULL,
  body TEXT NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id)
);

INSERT INTO users (id, tenant_id, name) VALUES
  (1, 1, '吉田東洋'),
  (6, 2, '西郷隆盛');

INSERT INTO posts (id, tenant_id, user_id, body)
VALUES (1, 1, 6, 'テナント境界を越えた投稿');
